const path = require('path');
const { getDefaultConfig, mergeConfig } = require('@react-native/metro-config');

// The catalog the lab apps share (../cells.json, generated by scripts/truth/catalog.ts) lies outside this app: Metro
// is told to watch the apps' folder, the other apps' builds kept out of its sight.
const apps = path.resolve(__dirname, '..');
const config = {
  watchFolders: [apps],
  resolver: {
    blockList: [/fixtures\/apps\/(ios|android)\/.*/, /fixtures\/apps\/rn\/(ios|android)\/build\/.*/, /fixtures\/apps\/rn\/ios\/Pods\/.*/],
  },
};

module.exports = mergeConfig(getDefaultConfig(__dirname), config);
